/**
 * Link version 1, frozen: the scenario channels.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 1 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV1.test.ts` checks the living types against it.
 */

import type { ScenarioDocumentV1, ScenarioIssueV1, ScenarioStateV1, SimulatedEventV1 } from './shapesScenarios';

export type ScenariosChannelsV1 = {
    'check-scenario': {
        args: [doc: unknown];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; issues: ScenarioIssueV1[] }
            | { success: true };
    };
    'delete-scenario': {
        args: [name: string];
        result: { success: true; error?: undefined } | { success: false; error: string };
    };
    'dry-run-scenario': {
        args: [challengeId: string | number];
        result:
            | { success: false; error: string; issues?: ScenarioIssueV1[] }
            | {
                  success: true;
                  scenario: string;
                  phase: string;
                  started: boolean;
                  halted: null | string;
                  manualOnly: boolean;
                  fire: null | { ruleId: string; startIndex: number; actions: string[] };
                  explain: { ruleId: string; label: string; status: 'ready' | 'blocked' | 'waiting'; reason: string }[];
                  nextWakeAt: null | number;
              };
    };
    'export-scenario': {
        args: [name: string];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; json?: undefined; omitted?: undefined }
            | { success: true; json: string; omitted: string[]; error?: undefined };
    };
    'get-scenario-status': {
        args: [challengeId: string | number];
        result:
            | { success: false; error: string; issues?: undefined }
            | {
                  serviceRuns: boolean;
                  manualOnly: boolean;
                  assigned: string;
                  scenario: null | ScenarioDocumentV1;
                  state: null | ScenarioStateV1;
                  corrupt: false | 'file' | 'record' | 'unloaded';
                  timezone: string;
                  success: true;
              };
    };
    'preview-scenario-import': {
        args: [text: string];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; issues: ScenarioIssueV1[] }
            | {
                  preview: {
                      name: string;
                      description: string;
                      start: string;
                      phases: { name: string; settings: string[]; rules: number }[];
                      spending: { phase: string; rule: undefined | string; action: string }[];
                      flagged: { phase: string; key: 'chosenPhotos' | 'chosenPhotosOnly' }[];
                      limits: { swaps?: number; keys?: number; fills?: number };
                  };
                  scenario: ScenarioDocumentV1;
                  exists: boolean;
                  success: true;
              };
    };
    'rename-scenario': {
        args: [oldName: string, newName: string];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; issues: ScenarioIssueV1[] }
            | { name: string; success: true };
    };
    'reset-scenario-state': {
        args: [challengeId: string | number];
        result: { success: false; error: string } | { success: true; error?: undefined };
    };
    'save-scenario': {
        args: [doc: unknown, options?: undefined | null | { overwrite?: boolean }];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; issues: ScenarioIssueV1[] }
            | { name: string; success: true };
    };
    'simulate-scenario': {
        args: [challengeId: string | number, draft?: unknown];
        result:
            | { success: false; error: string; issues?: ScenarioIssueV1[] }
            | {
                  events: SimulatedEventV1[];
                  stoppedBecause: 'limit' | 'halted' | 'closed' | 'idle';
                  stoppedAt: number;
                  halted: null | string;
                  success: true;
                  scenario: string;
                  startPhase: string;
                  now: number;
                  manualOnly: boolean;
              };
    };
};
